solution.solution.cpp:
#include <cctype>
#include <map>
#include <string>

enum class Kind { Event, Mutex, Semaphore };
enum class Result { Created, Opened, NotFound, WrongType };

class ObjectNamespace
{
public:
    Result create(Kind kind, const std::string& name, int& handle) { return get(kind, name, handle, true); }
    Result open(Kind kind, const std::string& name, int& handle) { return get(kind, name, handle, false); }

    void close(int handle)
    {
        const auto it{ handles.find(handle) };
        if (it == handles.end()) return;
        const std::string key{ it->second };
        handles.erase(it);
        if (--objects[key].count == 0) objects.erase(key);
    }

    bool exists(const std::string& name) const { return objects.count(lower(name)) > 0; }

    int handleCount(const std::string& name) const
    {
        const auto it{ objects.find(lower(name)) };
        return it == objects.end() ? 0 : it->second.count;
    }

private:
    struct Object { Kind kind; int count; };
    std::map<std::string, Object> objects;
    std::map<int, std::string> handles;
    int next{ 1 };

    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }

    Result get(Kind kind, const std::string& name, int& handle, bool mayCreate)
    {
        const std::string key{ lower(name) };
        const auto it{ objects.find(key) };
        if (it == objects.end())
        {
            if (!mayCreate) return Result::NotFound;
            objects[key] = { kind, 1 };
            handle = next++;
            handles[handle] = key;
            return Result::Created;
        }
        if (it->second.kind != kind) return Result::WrongType;
        ++it->second.count;
        handle = next++;
        handles[handle] = key;
        return Result::Opened;
    }
};

unitTests:
TEST("create, then the second create opens") {
    ObjectNamespace ns;
    int a{}, b{};
    CHECK(ns.create(Kind::Event, "Local\\xenon-ready", a) == Result::Created);
    CHECK(ns.create(Kind::Event, "LOCAL\\XENON-READY", b) == Result::Opened);
    CHECK(a != b);
    CHECK_EQ(ns.handleCount("local\\xenon-ready"), 2);
}
TEST("open never creates") {
    ObjectNamespace ns;
    int h{ -1 };
    CHECK(ns.open(Kind::Mutex, "lock", h) == Result::NotFound);
    CHECK_EQ(h, -1);
    CHECK(!ns.exists("lock"));
    int c{};
    ns.create(Kind::Mutex, "lock", c);
    CHECK(ns.open(Kind::Mutex, "lock", h) == Result::Opened);
}
TEST("one namespace for every kind") {
    ObjectNamespace ns;
    int a{}, b{ -1 };
    ns.create(Kind::Event, "shared", a);
    CHECK(ns.create(Kind::Mutex, "shared", b) == Result::WrongType);
    CHECK(ns.open(Kind::Semaphore, "shared", b) == Result::WrongType);
    CHECK_EQ(b, -1);
}
TEST("the last close destroys the object") {
    ObjectNamespace ns;
    int a{}, b{}, c{};
    ns.create(Kind::Semaphore, "slots", a);
    ns.open(Kind::Semaphore, "slots", b);
    ns.close(a);
    CHECK(ns.exists("slots"));
    ns.close(a);
    CHECK_EQ(ns.handleCount("slots"), 1);
    ns.close(b);
    CHECK(!ns.exists("slots"));
    CHECK(ns.create(Kind::Event, "slots", c) == Result::Created);
    CHECK(c > b);
}

